"""Render evidence-bounded M0 coverage and actionable gaps, without importing units."""
from collections import defaultdict
import gzip
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
BASE=ROOT/'artifacts/audits/municipal_m0_v1'


def main():
    analysis=json.loads(gzip.decompress((BASE/'analysis.json.gz').read_bytes()))
    proposals=json.loads((BASE/'proposals.json').read_text())
    summary=analysis['summary']
    def source(name): return json.loads(gzip.decompress((BASE/'sources'/f'{name}.json.gz').read_bytes()))
    dane={r['attributes']['MPIO_CDPMP']:r['attributes'] for r in source('divipola')['features'] if r['attributes']['MPIO_TIPO']=='MUNICIPIO'}
    gaps=defaultdict(lambda: {'physical_rows':defaultdict(int),'unique_ids':defaultdict(int),'profiles':set()})
    for row in analysis['strata']:
        if row['status']=='ACCREDITED_MUNICIPAL_AFFILIATION' and not row['covered']:
            gap=gaps[row['municipality']]
            gap['physical_rows'][row['dataset']]+=row['physical_rows']
            gap['unique_ids'][row['dataset']]+=row['unique_ids']
            gap['profiles'].add((row['account'],row['name']))
    ordered=sorted(gaps,key=lambda code:sum(gaps[code]['unique_ids'].values()),reverse=True)
    top=[dict(code=code,town=dane[code]['MPIO_CNMBRE'],department=dane[code]['DPTO_CNMBRE'],physical_rows=dict(gaps[code]['physical_rows']),unique_ids=dict(gaps[code]['unique_ids']),profiles=[{'account':a,'source_name':n} for a,n in sorted(gaps[code]['profiles'])]) for code in ordered[:25]]
    metrics={}
    for ds,volumes in summary['volumes'].items():
        known=volumes['ACCREDITED_MUNICIPAL_AFFILIATION'];unknown=volumes['UNRESOLVED_AFFILIATION']
        metrics[ds]={}
        for metric in ('physical_rows','unique_ids'):
            certified=known['covered_'+metric];denominator=known[metric]
            extra=proposals['summary']['additional_volume'][ds][metric]
            metrics[ds][metric]=dict(accredited_municipal_denominator=denominator,certified_recognized=certified,coverage_in_accredited_cohort=certified/denominator,unresolved_affiliation=unknown[metric],municipal_denominator_bounds=[denominator,denominator+unknown[metric]],certified_coverage_bounds=[certified/(denominator+unknown[metric]),certified/denominator],additional_if_proposals_imported=extra,cohort_coverage_after_proposals=(certified+extra)/denominator)
    catalog=json.loads((ROOT/'app/data/aliases_db.json').read_text())
    physical={ds:{r['name'] for r in analysis['strata'] if r['dataset']==ds} for ds in metrics}
    exact_missing=[dict(canonical=r['official_name'],observed_in_recent_dataset={ds:r['official_name'] in names for ds,names in physical.items()}) for r in catalog if not any(r['official_name'] in names for names in physical.values())]
    declared_nits=[dict(canonical=r['official_name'],declared_nit=r['nit']) for r in catalog if r.get('nit')]
    canary=next(p for p in proposals['proposals'] if p['code']=='08078')
    report=dict(stage='H_MUNICIPAL_M0',status='PARTIAL',reason='Bulk extraction and bounded automatic derivation PASS; complete municipal BuyerUnit denominator remains unadjudicated. Territory/account/name/NIT are not interchangeable identities.',window=['2025-09-03','2026-09-03'],nominal=dict(divipola_territories=len(dane),accredited_active=summary['accredited_active_municipal_territories'],recognized=summary['recognized_municipal_territories'],recognized_over_divipola=summary['recognized_municipal_territories']/len(dane),recognized_over_accredited_active=summary['recognized_municipal_territories']/summary['accredited_active_municipal_territories'],additional_territories=proposals['summary']['additional_nominal_municipal_territories']),activity=metrics,recognized_buyer_units=summary['accredited_recognized_buyer_units'],automatic_derivation=proposals['summary'],baranoa_canary=canary,top_municipal_gaps=top,catalog_debts=dict(declared_nit_records=declared_nits,canonicals_not_observed_byte_for_byte_recent=exact_missing,interpretation='Absence in this annual snapshot is not proof of a phantom canonical: source projections and inactivity must be adjudicated. No source/NIT corrections or merges were applied.'),runtime_fingerprint={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in (ROOT/'app/data/aliases_db.json',ROOT/'app/data/buyer_source_names.json',ROOT/'app/data/buyer_groups.json')},production_import=False)
    (BASE/'summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
    fmt=lambda n:f'{n:,}'.replace(',','.')
    pct=lambda n:f'{100*n:.2f}%'.replace('.',',')
    lines=['# Municipal M0 — cobertura acreditada y deuda de afiliación','', '**Estado: PARTIAL.** Extracción bulk, conciliación y propuestas automáticas: PASS. El porcentaje exacto de todo el universo municipal de BuyerUnits todavía no es identificable con estas fuentes sin adjudicar los casos pendientes. Se publican denominadores, cotas y perfiles pendientes; ninguno se convierte en una unidad por compartir NIT o ubicación.','', '## Fuentes y alcance','', '- [DIVIPOLA DANE 2025](https://portalgis.dane.gov.co/mparcgis/rest/services/Divipola/Serv_DIVIPOLA_MGN_2025/MapServer/317): 1.122 territorios; 1.103 municipios/distritos, 18 áreas no municipalizadas y una isla. Sólo los 1.103 entran al denominador municipal.', '- [Directorio SECOP II](https://www.datos.gov.co/resource/4ex9-j3n8.json): 27.297 estratos de registros con `es_entidad=Si`. Un código de cuenta aporta procedencia, no identidad lógica.', '- [SIGEP, reporte oficial 61](https://www.funcionpublica.gov.co/VisualSIE/faces/reporte/publico.xhtml?externo=true&idConsulta=Pr&idReporte=61): exportación completa de 6.300 entidades activas; 5.543 de suborden Municipal y 182 Distrital. El suborden acredita adscripción; el NIT sólo genera candidatos para contrastar nombre, cuenta y territorio.', '- [Procesos SECOP II](https://www.datos.gov.co/resource/p6dx-8zbt.json) y [contratos SECOP II](https://www.datos.gov.co/resource/jbjy-vk9h.json): ventana `[2025-09-03, 2026-09-03)`. 1.885.602 filas de procesos / 1.819.018 procesos únicos; 1.095.013 filas y contratos únicos.', '', 'Los conteos antes/después coinciden con la suma de estratos. La suma de procesos únicos por estrato coincide con el DISTINCT global; en contratos existe igualdad global entre filas e IDs distintos. Esa prueba habilita sumar las métricas lógicas por cohorte sin deduplicar por NIT. El primer agregado de contratos agotó 55 segundos; el reintento redujo dimensiones y mantuvo conciliación completa. Se preserva la evidencia de ambas llamadas.', '', 'La vía de afiliación SIGEP exige directorio por cuenta + nombre institucional + evidencia fiscal + DIVIPOLA + SIGEP de jurisdicción única. Para ejecutivos se reutiliza la familia institucional existente y se exige el municipio completo en los dos nombres. Un nombre territorial aislado no acredita pertenencia. La vía alternativa de Bogotá usa su registro ejecutivo declarado y exige coincidencia exacta con nombre, cuenta y evidencia fiscal del lote acreditado de G; no genera membresía desde geografía o NIT.', '', '## Cobertura medida','', f"Hay **{summary['accredited_active_municipal_territories']} municipios con actividad municipal acreditada** y **{summary['recognized_municipal_territories']} reconocidos con alcance comprobado** ({pct(report['nominal']['recognized_over_accredited_active'])} de esa cohorte; {pct(report['nominal']['recognized_over_divipola'])} de DIVIPOLA). Se certificaron {summary['accredited_recognized_buyer_units']} BuyerUnits existentes sin reclamaciones físicas compartidas. Los demás territorios no se declaran inactivos.", '', '| Dataset / métrica | Cohorte municipal acreditada | Reconocido comprobado | Cobertura de la cohorte | Afiliación pendiente |','|---|---:|---:|---:|---:|']
    for ds,label in [('p6dx-8zbt','Procesos'),('jbjy-vk9h','Contratos')]:
        for metric,mlabel in [('physical_rows','filas físicas'),('unique_ids','IDs únicos')]:
            m=metrics[ds][metric]
            lines.append(f"| {label}: {mlabel} | {fmt(m['accredited_municipal_denominator'])} | {fmt(m['certified_recognized'])} | {pct(m['coverage_in_accredited_cohort'])} | {fmt(m['unresolved_affiliation'])} |")
    lines+=['', 'La afiliación pendiente mezcla posibles compradores municipales con otros territoriales y ruido de registro. No se llama municipal a todo ese residuo. El denominador municipal de procesos únicos queda entre '+fmt(metrics['p6dx-8zbt']['unique_ids']['municipal_denominator_bounds'][0])+' y '+fmt(metrics['p6dx-8zbt']['unique_ids']['municipal_denominator_bounds'][1])+'; el de contratos únicos entre '+fmt(metrics['jbjy-vk9h']['unique_ids']['municipal_denominator_bounds'][0])+' y '+fmt(metrics['jbjy-vk9h']['unique_ids']['municipal_denominator_bounds'][1])+'. Las cotas se refieren al volumen; no convierten cuentas o strings en BuyerUnits.', '', '## Incorporación derivable','', f"**{proposals['summary']['eligible_executive_municipalities']} ejecutivos municipales** cumplen el predicado conservador: {proposals['summary']['dispositions']['ADD_NEW_ACCREDITED_UNIT']} unidades nuevas y {proposals['summary']['dispositions']['ADD_ALIASES_TO_EXISTING_UNIT']} ampliaciones de alias. Representan **{proposals['summary']['additional_nominal_municipal_territories']} territorios adicionales**, porque dos ya tienen otra unidad municipal reconocida.", '', 'El predicado requiere nombre físico byte-idéntico en ambos datasets, una única cuenta observada, evidencia fiscal consistente, afiliación acreditada por SIGEP/directorio/DIVIPOLA, cero conflictos de alias o proyección, y comprobación histórica de propietarios por nombre exacto. Las 58 consultas por lotes verifican los propietarios sin hacer 1.103×N consultas. Los pares de grafías, múltiples cuentas y evidencia fiscal divergente quedan fuera; no se fusionan.', '', f"Los **{proposals['summary']['alias_checks']} alias propuestos** resolvieron exactamente y con propietario único en un catálogo temporal: cero fallos. Aportarían {fmt(proposals['summary']['additional_volume']['p6dx-8zbt']['unique_ids'])} procesos únicos y {fmt(proposals['summary']['additional_volume']['jbjy-vk9h']['unique_ids'])} contratos únicos de la ventana. Es capacidad comprobada sobre estas capturas, no garantía ante cambios futuros de la fuente. **No se importó ninguna propuesta en producción.**", '', f"Baranoa (08078) entra por la misma regla: `{canary['canonical']}`, cuenta `{canary['account']}`, {canary['volumes']['p6dx-8zbt']['physical_rows']} filas / {canary['volumes']['p6dx-8zbt']['unique_ids']} procesos únicos y {canary['volumes']['jbjy-vk9h']['unique_ids']} contratos únicos. No hay excepción por municipio en el código.", '', '## Principales brechas acreditadas por actividad','', '| Municipio | Departamento | Procesos únicos sin cubrir | Contratos únicos sin cubrir |','|---|---|---:|---:|']
    for r in top[:15]: lines.append(f"| {r['town']} | {r['department']} | {fmt(r['unique_ids'].get('p6dx-8zbt',0))} | {fmt(r['unique_ids'].get('jbjy-vk9h',0))} |")
    lines+=['', '## Deudas y reproducción','', 'Permanece abierta la adjudicación del residuo territorial y la cardinalidad completa de BuyerUnits municipales. Los perfiles pendientes conservan cuenta, nombre, dataset y evidencia fiscal en el artefacto; no se presentan como compradores lógicos distintos ni se consolidan automáticamente.', '', f"El censo detecta {len(exact_missing)} canonicals sin aparición byte-for-byte en la ventana y {len(declared_nits)} registros con NIT declarado. Son colas de revisión: ausencia reciente no prueba un canonical fantasma. El NIT transpuesto de Ibagué documentado en P0.1 no aparece en el catálogo de runtime auditado. No se corrigieron NIT ni se crearon merges para mejorar métricas.", '', 'Evidencia íntegra: `artifacts/audits/municipal_m0_v1/`, con SHA-256, SoQL literal, estados de extracción, matriz de afiliación, métricas y propuestas. Las capturas están comprimidas; SIGEP conserva únicamente columnas necesarias para identidad y afiliación.', '', 'Reproducir sin red:', '', '```bash', '.venv/bin/python3 scripts/audits/audit_municipal_m0.py', '.venv/bin/python3 scripts/audits/audit_municipal_m0_proposals.py', '.venv/bin/python3 scripts/audits/summarize_municipal_m0.py', '```', '', 'No hay mutación de runtime en M0. Los gates y el commit de cierre se registran en `INSTITUTIONAL_BUYER_INTEGRITY_GROUPS_V1.md`.']
    (ROOT/'docs/gazetteer/MUNICIPAL_M0_V1.md').write_text('\n'.join(lines)+'\n')
    print(json.dumps({k:report[k] for k in ('status','nominal','automatic_derivation')},ensure_ascii=False,indent=2))


if __name__=='__main__': main()
